<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/finance_step16.php';if(empty($_SESSION['flb_csrf']))$_SESSION['flb_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['flb_csrf'];$error=null;$success=null;$accounts=[];$income=[];$royalty=[];
try{$pdo=business_db();finance_step16_ensure($pdo);$ctx=finance_step16_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$jid=finance_step16_post_legacy_receipt($pdo,(string)($_POST['kind']??''),(int)($_POST['source_id']??0),(int)($_POST['cash_account_id']??0));$success='Legacy operational income confirmed as received money in Journal #'.$jid.'.';}$accounts=finance_step16_accounts($pdo,$orgId);$rev=BUSINESS_REVERSED_SOURCE_SHEET;$stmt=$pdo->prepare("SELECT i.id,i.income_date txn_date,i.income_type label,i.amount,i.source_sheet,i.source_row FROM income_entries i WHERE i.organization_id=? AND i.amount>0 AND COALESCE(i.source_sheet,'')<>? AND NOT EXISTS(SELECT 1 FROM finance_source_links f WHERE f.organization_id=i.organization_id AND f.source_type='legacy_income' AND f.source_id=i.id AND f.event_key='confirmed_receipt' AND f.status='active') ORDER BY i.income_date DESC,i.id DESC LIMIT 120");$stmt->execute([$orgId,$rev]);$income=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT r.id,COALESCE(r.royalty_date,DATE(r.created_at)) txn_date,COALESCE(r.period_label,'Royalty') label,r.amount,r.source_sheet,r.source_row FROM royalty_entries r WHERE r.organization_id=? AND r.amount>0 AND COALESCE(r.source_sheet,'')<>? AND NOT EXISTS(SELECT 1 FROM finance_source_links f WHERE f.organization_id=r.organization_id AND f.source_type='legacy_royalty' AND f.source_id=r.id AND f.event_key='confirmed_receipt' AND f.status='active') ORDER BY COALESCE(r.royalty_date,DATE(r.created_at)) DESC,r.id DESC LIMIT 120");$stmt->execute([$orgId,$rev]);$royalty=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function lb_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function lb_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Legacy Finance Bridge - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="finance_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 16 • Legacy Finance Bridge</small></span></a><div class="os-top-actions"><a class="os-btn" href="finance_accounts.php">Accounts</a><a class="os-btn" href="finance_journal.php">Journal</a><a class="os-btn primary" href="finance_center.php">Finance Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Finance</div><nav class="os-nav"><a href="finance_center.php"><i class="dot"></i>Finance Center</a><a class="active" href="finance_legacy_bridge.php"><i class="dot"></i>Legacy Finance Bridge</a><a href="finance_cashbook.php"><i class="dot"></i>Cashbook</a><a href="step16_audit.php"><i class="dot"></i>Audit</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 16I • LEGACY CASH CONFIRMATION</div><h1>Operational income is not automatically treated as cash received.</h1><p>Select a real/clearing account only when the historical income or royalty amount was actually received. This preserves the workbook facts without inventing historical bank balances.</p><div class="os-status-row"><span class="os-chip"><?= count($income) ?> income pending</span><span class="os-chip"><?= count($royalty) ?> royalty pending</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Legacy bridge diagnostic:</strong> <?= lb_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Confirmed:</strong> <?= lb_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-6"><h2>Monthly Income / Business Income</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Type</th><th>Amount</th><th>Source</th><th>Confirm Receipt</th></tr></thead><tbody><?php foreach($income as $r):?><tr><td><?= lb_h($r['txn_date']) ?></td><td><?= lb_h($r['label']) ?></td><td><b><?= lb_m($r['amount']) ?></b></td><td><?= lb_h($r['source_sheet']) ?><small>Row <?= (int)($r['source_row']??0) ?></small></td><td><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= lb_h($csrf) ?>"><input type="hidden" name="kind" value="income"><input type="hidden" name="source_id" value="<?= (int)$r['id'] ?>"><select name="cash_account_id" required><option value="">Received into…</option><?php foreach($accounts as $a):?><option value="<?= (int)$a['id'] ?>"><?= lb_h($a['account_name'].($a['is_system_clearing']?' • Clearing':'')) ?></option><?php endforeach;?></select><button>Confirm</button></form></td></tr><?php endforeach;?><?php if(!$income):?><tr><td colspan="5">No unconfirmed positive income entries.</td></tr><?php endif;?></tbody></table></div></article><article class="os-card pp-span-6"><h2>Royalty Income</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Period</th><th>Amount</th><th>Source</th><th>Confirm Receipt</th></tr></thead><tbody><?php foreach($royalty as $r):?><tr><td><?= lb_h($r['txn_date']) ?></td><td><?= lb_h($r['label']) ?></td><td><b><?= lb_m($r['amount']) ?></b></td><td><?= lb_h($r['source_sheet']) ?><small>Row <?= (int)($r['source_row']??0) ?></small></td><td><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= lb_h($csrf) ?>"><input type="hidden" name="kind" value="royalty"><input type="hidden" name="source_id" value="<?= (int)$r['id'] ?>"><select name="cash_account_id" required><option value="">Received into…</option><?php foreach($accounts as $a):?><option value="<?= (int)$a['id'] ?>"><?= lb_h($a['account_name'].($a['is_system_clearing']?' • Clearing':'')) ?></option><?php endforeach;?></select><button>Confirm</button></form></td></tr><?php endforeach;?><?php if(!$royalty):?><tr><td colspan="5">No unconfirmed positive royalty entries.</td></tr><?php endif;?></tbody></table></div></article></section><div class="os-footer-note"><strong>Important:</strong> clicking Confirm asserts that this operational income amount was actually received into the selected account. Do not confirm merely because the amount exists in Excel.</div><?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
